// Mascara dados pessoais e detecta urgência antes de qualquer chamada externa.
const b = $json.body || {};
const txt = String(b.texto || '').slice(0, 1000);
const mask = s => s
  .replace(/\b\d{3}\.?\d{3}\.?\d{3}-?\d{2}\b/g, '[cpf]')
  .replace(/\b\d{12,20}\b/g, '[carteirinha]')
  .replace(/\(?\d{2}\)?\s?9?\d{4}-?\d{4}/g, '[telefone]')
  .replace(/[\w.+-]+@[\w-]+\.[\w.]+/g, '[email]')
  .replace(/(meu nome (é|e)|me chamo)\s+[^,.!?]+/gi, '$1 [nome]');
const urg = /(dor no peito|falta de ar|não consigo respirar|desmai|sangrando muito|convuls|avc|derrame|infarto|suic|me matar|overdose)/i.test(txt);
const hist = (b.historico || []).slice(-6).map(m => ({ role: m.role === 'assistant' ? 'assistant' : 'user', content: mask(String(m.content || '')).slice(0, 600) }));
return { json: { correlation_id: b.correlation_id || ('CONV-' + Date.now().toString(36)), canal: b.canal || 'app',
  modo: b.modo_infantil === true ? 'infantil' : 'geral', texto: mask(txt), historico: hist, urgencia: urg } };

// Monta as mensagens com o contexto aprovado (RAG) e as regras da Daisy.
const base = $('Mascarar dados e checar urgência').first().json;
const ctx = $input.all().map(i => i.json).filter(r => r && r.texto).map(r => '- ' + r.titulo + ': ' + r.texto).join('\n') || '(sem conteúdo aprovado para esta pergunta)';
const SYSTEM = "Você é a Daisy, assistente virtual do hospital. Neste modo você só conversa: tira dúvidas gerais sobre o hospital usando apenas o CONTEXTO aprovado e conta curiosidades e histórias curtas e gentis. Regras: 1) Não faz diagnóstico, não fala de doses, remédios, resultados de exames, preços, cobertura de convênio e não opina sobre médicos ou equipes. 2) Não agenda, não cancela, não cobra e não consulta fila. Se o paciente pedir algo assim, responda só [[VOLTAR_AO_10]]. 3) Se a dúvida sobre o hospital não estiver no CONTEXTO, diga que não tem essa informação e ofereça o atendente humano (opção 11). 4) Nunca peça nome, CPF, carteirinha, endereço ou telefone. 5) Em modo infantil: linguagem simples, histórias de até 150 palavras, sem medo, violência ou temas adultos, e sem perguntar dados da criança. 6) Até 120 palavras, português do Brasil, tom acolhedor.";
return [{ json: { ...base, contexto_itens: $input.all().filter(i => i.json && i.json.texto).length,
  body: { model: $env.OPENAI_MODEL, temperature: 0.6, max_tokens: 400,
    messages: [{ role: 'system', content: SYSTEM + '\nModo: ' + base.modo + '.\nCONTEXTO:\n' + ctx }, ...base.historico, { role: 'user', content: base.texto }] } } }];

// Filtro de saída: devolve ao Agente IA (10) se o assunto for transacional; bloqueia dose ou preço.
const base = $('Montar mensagens').item.json;
let txt = String((($json.choices || [])[0] || {}).message?.content || '').trim();
let acao = 'respondido';
if (txt.includes('[[VOLTAR_AO_10]]')) { acao = 'voltar_ao_10'; txt = ''; }
else if (/\b\d+([.,]\d+)?\s?(mg|ml|mcg|gotas|comprimidos?)\b/i.test(txt) || /R\$\s?\d/.test(txt)) {
  acao = 'bloqueado_saida';
  txt = 'Sobre remédios, doses ou valores, quem orienta é a equipe do hospital. Quer que eu chame um atendente (opção 11)?';
}
if (!txt && acao === 'respondido') { acao = 'sem_resposta'; txt = 'Não consegui responder agora. Posso chamar um atendente (opção 11)?'; }
return { json: { correlation_id: base.correlation_id, canal: base.canal, modo: base.modo, acao, resposta: txt,
  contexto_itens: base.contexto_itens, tokens: ($json.usage || {}).total_tokens || null } };
